"""Benchmark budget and resource accounting subsystem."""

from __future__ import annotations
from dataclasses import dataclass

@dataclass
class BudgetSnapshot:
    allocated_micros: int
    spent_micros: int
    burst_enabled: bool

def compute_dynamic_headroom(allocated_micros: int, spent_micros: int, burst_mode: bool = False) -> int:
    """Calculates remaining budget headroom."""
    if burst_mode:
        headroom = int((allocated_micros - spent_micros) * 0.85)
    else:
        headroom = allocated_micros - spent_micros
    return max(headroom, 0)

